tool_args.command:
python3 -c "import json; d=json.load(open('/root/autodl-tmp/rl-active-probe-fl/eto_repo/data/alfworld_sft.json')); task_types={}; rewards=[]; 
for item in d:
    gf = item.get('game_file','') or ''
    for t in ['look_at_obj','pick_and_place','pick_clean_then_place','pick_heat_then_place','pick_cool_then_place','pick_two_obj']:
        if t in gf:
            task_types[t] = task_types.get(t,0)+1
            break
    rewards.append(item.get('reward',None))
print('Task types:', task_types)
print('Total with reward:', sum(1 for r in rewards if r is not None))
print('Rewards: success=', sum(1 for r in rewards if r==1 or r==True), 'fail=', sum(1 for r in rewards if r==0 or r==False))"
